//! Cargo-driven `usbccgp.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is usbccgp-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "DriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DriverEntry", 0x7ffb00000000u64),
        o => panic!("usbccgp-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:pseh", "import:ntoskrnl", "import:hal", "import:usbd", "engine:chkstk", "engine:c:memcmp"],
        "x86_64" => &["body", "engine:pseh", "import:ntoskrnl", "import:hal", "import:usbd", "engine:c:memcmp"],
        "aarch64" => &["body", "engine:pseh", "import:ntoskrnl", "import:hal", "import:usbd", "engine:chkstk", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=-sse,-sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("usbccgp-rust")
        .rust_user_target()
        .resource_from_rc("drivers/usb/usbccgp/usbccgp.rc", "usbccgp_res")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        .import_lib("drivers/usb/usbd/usbd.spec", "usbd.sys", "usbd")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
